pub(crate) fn on_on_stars_spent_mini_regent(
    state: &mut CombatState,
    ctx: &crate::hooks::StarsSpentCtx,
) -> EffectResult {
    if !player_owns_relic(state, crate::RelicKind::MiniRegent) {
        return EffectResult::NotImplemented;
    }
    if ctx.amount <= 0 {
        return EffectResult::NotImplemented;
    }
    // Flip the per-turn flag first; if already used, bail without
    // applying. The Python body bails before the apply for the same
    // reason.
    let armed = if let Some(r) = mini_regent_relic_mut(state) {
        if r.counter != 0 {
            return EffectResult::NotImplemented;
        }
        r.counter = 1;
        true
    } else {
        false
    };
    if !armed {
        return EffectResult::NotImplemented;
    }
    let Some(player_uid) = state.player.creature_uid else {
        return EffectResult::NotImplemented;
    };
    crate::card_effects::apply_power_to_creature(
        state,
        player_uid,
        crate::PowerKind::Strength,
        MINI_REGENT_STRENGTH,
    );
    EffectResult::Resolved
}

/// `MiniRegent.before_side_turn_start` — clear the `_used_this_turn`
/// flag at the start of each player side-turn so the next spend
/// re-triggers. Bead `sts2-rs-5ans`.
pub(crate) fn on_before_side_turn_start_mini_regent(
    state: &mut CombatState,
    side: Side,
) -> EffectResult {
    if side != Side::Player {
        return EffectResult::NotImplemented;
    }
    if let Some(r) = mini_regent_relic_mut(state) {
        r.counter = 0;
        EffectResult::Resolved
    } else {
        EffectResult::NotImplemented
    }
}

